import subprocess
import os

def task_func(script_path, wait=True, *args):
    # Check if the script exists
    if not os.path.exists(script_path):
        raise ValueError(f"The script does not exist: {script_path}")

    # Construct the command to run the script with arguments
    command = [sys.executable, script_path] + list(args)

    try:
        # Start the subprocess
        process = subprocess.Popen(command)

        # Wait for the process to complete if wait is True
        if wait:
            process.wait()
            return process.returncode
        else:
            return None
    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(e.returncode, e.cmd, e.output, e.stderr)

import xlwt
import os
import json
import pandas as pd

def task_func(json_str, filename, sheet_name="sheet1"):
    # Check if json_str is a string, bytes, or bytearray
    if not isinstance(json_str, (str, bytes, bytearray)):
        raise TypeError("json_str must be a string, bytes, or bytearray")

    # Load JSON data
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        raise ValueError("json_str is not valid JSON")

    # Create a DataFrame from the JSON data
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Error creating DataFrame: {e}")

    # Write the DataFrame to an Excel file
    try:
        with pd.ExcelWriter(filename, engine='xlsxwriter') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=False)
    except Exception as e:
        raise Exception(f"Error writing to Excel file: {e}")

    # Return the absolute path of the created Excel file
    return os.path.abspath(filename)

import binascii
import hashlib
import os
import re

OUTPUT_DIR = './output'

def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    file_hashes = {}

    # Compile the regex pattern
    regex = re.compile(pattern)

    # Walk through the directory
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)

            # Check if the file path matches the regex pattern
            if regex.search(file_path):
                # Compute SHA256 hash of the file's content
                sha256_hash = hashlib.sha256()
                try:
                    with open(file_path, 'rb') as f:
                        for byte_block in iter(lambda: f.read(4096), b""):
                            sha256_hash.update(byte_block)
                    file_hashes[file_path] = sha256_hash.hexdigest()
                except Exception as e:
                    print(f"Error reading file {file_path}: {e}")

    return file_hashes

import itertools
import random

def task_func(t, n):
    # Generate all combinations of length n from the tuple t
    combinations = list(itertools.combinations(t, n))

    # If there are no combinations, return an empty tuple
    if not combinations:
        return ()

    # Return a random combination from the list of combinations
    return random.choice(combinations)

import os

def task_func(directory, word):
    count = 0
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                    if word in content:
                        count += 1
            except Exception as e:
                # Handle the exception if needed, e.g., print the error message
                pass
    return count

import shutil
import pathlib
from typing import List, Tuple

def task_func(source_path: str, destination_path: str) -> Tuple[str, List[str]]:
    source = pathlib.Path(source_path)
    destination = pathlib.Path(destination_path)

    if not source.exists() or not source.is_dir():
        raise ValueError("source_path does not exist or is not a directory.")

    if not destination.exists():
        destination.mkdir(parents=True)

    copied_files = []
    for item in source.iterdir():
        if item.is_file():
            shutil.copy(item, destination)
            copied_files.append(item.name)

    return source.name, copied_files
